display.text:
"use client";

import { useEffect, useRef } from "react";
import { supabaseClient } from "@/lib/supabase-client";
import { useThreadStore } from "@/stores/thread-store";
import type { RealtimeChannel } from "@supabase/supabase-js";

interface MessageContentPart {
  type: string;
  text?: string;
  [key: string]: unknown;
}

interface UseRealtimeThreadOptions {
  threadId: string;
  onActivity?: (activity: {
    id: string;
    type: string;
    status: string;
    title: string;
    stepLabel?: string;
    detail?: unknown;
  }) => void;
}

export function useRealtimeThread({ threadId, onActivity }: UseRealtimeThreadOptions) {
  const threadIdRef = useRef(threadId);

  useEffect(() => {
    threadIdRef.current = threadId;
  }, [threadId]);

  useEffect(() => {
    const sid = threadIdRef.current;
    if (!sid) return;

    const channel = supabaseClient
      .channel(`thread:${sid}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "chat_messages",
          filter: `thread_id=eq.${sid}`,
        },
        (payload: { new?: { id: string; role: string; content: unknown; status: string } }) => {
          const message = payload.new;
          if (!message) return;

          useThreadStore.getState().addMessage({
            id: message.id,
            role: message.role as "user" | "assistant",
            content: (message.content as MessageContentPart[]) || [],
            status: message.status,
          });
        }
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "chat_messages",
          filter: `thread_id=eq.${sid}`,
        },
        (payload: { new?: { id: string; status: string; content: unknown }; old?: { id: string; status: string; content: unknown } }) => {
          const message = payload.new;
          const oldMessage = payload.old;
          if (!message || !oldMessage) return;

          if (message.status !== oldMessage.status) {
            useThreadStore.getState().updateMessage(message.id, {
              status: message.status,
            });
          }

          if (message.content && JSON.stringify(message.content) !== JSON.stringify(oldMessage.content)) {
            useThreadStore.getState().updateMessage(message.id, {
              content: message.content as MessageContentPart[],
            });
          }
        }
      )
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "run_activities",
        },
        async (payload: { new?: { id: string; type: string; status: string; title: string; run_id: string; step_label?: string; detail?: unknown } }) => {
          const activity = payload.new;
          if (!activity) return;

          const threadRes = await supabaseClient
            .from("runs")
            .select("thread_id")
            .eq("id", activity.run_id)
            .maybeSingle();

          if (threadRes.data?.thread_id !== sid) return;

          onActivity?.({
            id: activity.id,
            type: activity.type,
            status: activity.status,
            title: activity.title,
            stepLabel: activity.step_label,
            detail: activity.detail,
          });
        }
      )
      .subscribe();

    return () => {
      supabaseClient.removeChannel(channel);
    };
  }, [onActivity]);
}

