  setText: (text: string) => void;
  setTokenStep: (step: 1 | 2 | 3 | 4 | 5) => void;
  getTokenCount: () => number;
}

export const useComposerStore = create<ComposerState>()((set, get) => ({
  text: "",
  tokenStep: 3,
  setText: (text) => set({ text }),
  setTokenStep: (tokenStep) => set({ tokenStep }),
  getTokenCount: () => TOKEN_STEPS[get().tokenStep - 1],
}));

