import { create } from "zustand";

interface MessageContentPart {
  type: string;
  text?: string;
  [key: string]: unknown;
}

interface ThreadMessage {
  id: string;
  role: "user" | "assistant";
  content: MessageContentPart[];
  status: string;
}

interface RunState {
  id: string;
  status: string;
}

interface ThreadState {
  thread: { id: string; title: string; boundWorkflowId: string | null } | null;
  messages: ThreadMessage[];
  run: RunState | null;
  isLoading: boolean;
  setThread: (thread: ThreadState["thread"]) => void;
  setMessages: (messages: ThreadState["messages"]) => void;
  addMessage: (message: ThreadMessage) => void;
  updateMessage: (id: string, updates: Partial<ThreadMessage>) => void;
  setRun: (run: ThreadState["run"]) => void;
  setLoading: (loading: boolean) => void;
}

export const useThreadStore = create<ThreadState>()((set) => ({
  thread: null,
  messages: [],
  run: null,
  isLoading: false,
  setThread: (thread) => set({ thread }),
  setMessages: (messages) => set({ messages }),
  addMessage: (message) =>
    set((state) => ({ messages: [...state.messages, message] })),
  updateMessage: (id, updates) =>
    set((state) => ({
      messages: state.messages.map((m) =>
        m.id === id ? { ...m, ...updates } : m
      ),
    })),
  setRun: (run) => set({ run }),
  setLoading: (isLoading) => set({ isLoading }),
}));

