+				rightSlot={
+					<DropdownMenu>
+						<DropdownTrigger
+							render={
+								<Button variant="ghost" size="sm" trailingIcon={ChevronDownIcon}>
+									{formatTokens(TOKEN_STEPS[tokenStep - 1] ?? 4096)}
+								</Button>
+							}
+						/>
+						<DropdownContent>
+							<Slider
+								label="Output tokens"
+								className="p-4"
+								value={tokenStep}
