                     setPendingThreadGroupId(group.id);
                     setNewThreadOpen(true);
                   }}
                 >
                   <PlusIcon />
                 </SidebarGroupAction>
               </Tooltip>
               <DropdownMenu>
                 <Tooltip content="Section settings" side="top">
                   <DropdownTrigger
