                     label="Run all"
                     onSelect={() => {}}
                   />
                   <MenuItem
                     index={1}
                     icon={StopIcon}
                     label="Stop all"
                     onSelect={() => {}}
                   />
                   <MenuItem
                     index={2}
                     icon={PencilIcon}
