                     onSelect={() => openRenameGroup(group.id, group.name)}
                   />
 
                   <DropdownSeparator />
 
                   <MenuItem
                     index={3}
                     icon={DeleteIcon}
                     label="Delete section"
                     onSelect={() => confirmDeleteGroup(group.id, group.name)}
                   />
                   <MenuItem
                     index={4}
                     icon={DeleteIcon}
                     label="Delete all threads"
                     onSelect={() =>
                       confirmDeleteGroupThreads(
                         group.id,
                         group.name,
                         group.threads.map((t) => ({
                           value: t.title || "Untitled",
