                 alt=""
                 className="size-5 rounded-full object-cover"
               />
             ) : (
               <span className="flex size-5 items-center justify-center rounded-full bg-muted-foreground text-[10px] text-background">
                 {(user?.name || user?.email || "A").charAt(0).toUpperCase()}
               </span>
             )
           }
           menu={
             <>
               <MenuItem
                 index={0}
                 icon={UserIcon}
                 label="Profile"
                 onSelect={() => {}}
               />
 
               <MenuItem
                 index={2}
                 icon={ArrowLeftIcon}
                 label="Log out"
                 onSelect={() => {}}
               />
             </>
           }
         />
       </SidebarFooter>
     </Sidebar>
   );
 }

